"""Create original planning guides and a services index with the established site styles."""
from pathlib import Path
import runpy

ROOT = Path(__file__).resolve().parents[1]
api = runpy.run_path(str(ROOT / 'research/build-growth-pages.py'))
render, section, services = api['render'], api['section'], api['SERVICES']

GUIDES = [
    ('wordpress-to-nextjs-migration-checklist', 'WordPress to Next.js Migration Checklist | Content & SEO',
     'Plan a WordPress to Next.js migration around content, editor preview, public URLs and launch checks. Includes an original downloadable inventory and redirect example.',
     'WordPress to Next.js migration checklist',
     'A separate frontend changes more than page templates. Use this planning workflow to agree what stays in WordPress, how editors publish and what happens to existing URLs before the build starts.', [
         ('Start with the reason for the change', '<p>A custom interface or a shared content source can justify a headless setup. If the existing WordPress site already meets the publishing and presentation needs, the additional frontend may add maintenance without solving a useful problem.</p><p>Write down the outcome first: a different visitor journey, reusable content across products or a specific interaction requirement. Separate that goal from an assumption that a framework alone will improve traffic.</p>'),
         ('Inventory content and public behavior', '<p>List page types, posts, media, menus, custom fields, forms and integrations. Include category/archive pages and downloads where visitors or links depend on them. Record what remains, what changes and who decides.</p><p><a href="/resources/migration-content-inventory.csv" download>Download the synthetic content inventory</a>. It uses a fictional campus with a building page, availability, contact and a brochure. It is a planning example, not a record of a client migration.</p><div class="tool-table-wrap" tabindex="0" role="region" aria-label="Content inventory example"><table class="tool-table"><thead><tr><th>Existing item</th><th>Decision</th><th>Owner</th></tr></thead><tbody><tr><td>Building page</td><td>Keep URL; rebuild template</td><td>Content and frontend owners</td></tr><tr><td>Availability data</td><td>Confirm source and update path</td><td>Property operations</td></tr><tr><td>Enquiry form</td><td>Recheck delivery and error behavior</td><td>Lead recipient and developer</td></tr></tbody></table></div>'),
         ('Map editor fields to the page', '<p>For each page section, agree the content fields and how missing values behave. An editor changing a title is different from redesigning the layout. Make those boundaries visible before content entry starts.</p><pre><code>building.name        -&gt; page heading\nbuilding.introduction -&gt; introductory copy\nbuilding.brochure     -&gt; brochure link, when provided\nbuilding.availability -&gt; reviewed availability section</code></pre><p>The <a href="/resources/cms-content-example.json" download>synthetic CMS example</a> gives these fields a concrete value. My <a href="/project-case-study-2.html">Cambridge Research Park case study</a> documents related Next.js/WordPress integration work; the inventory here is a separate demonstration.</p>'),
         ('Agree preview and publishing', '<p>Define how an editor sees a draft, who may access it and how a published change reaches the public frontend. Test a normal edit, missing media and a scheduled update where scheduling is required.</p><p><a href="https://nextjs.org/docs/app/guides/draft-mode">Next.js Draft Mode</a> is one platform mechanism for previewing draft content. Authentication, content fetching and publishing behavior still need to match the chosen CMS and application.</p>'),
         ('Preserve useful URLs and map changes', '<p>Keep existing addresses where they still represent the same content. For addresses that change, choose a relevant destination and record the decision. A spreadsheet can reveal contradictory rules, but it cannot decide whether the new page satisfies the visitor\'s original need.</p><p>Use the <a href="/tools/redirect-map-checker/">redirect-map checker</a> for supported structural checks and missing inventory decisions. Confirm deployed responses separately. Google\'s <a href="https://developers.google.com/search/docs/crawling-indexing/site-move-with-url-changes">migration guidance</a> explains the wider URL-change process.</p>'),
         ('Review the release as a complete journey', '<ul><li><strong>Search discovery</strong> Review public content, titles, canonicals, index directives, internal links and sitemap URLs.</li><li><strong>Editor workflow</strong> Confirm preview, publish and content ownership with someone who will maintain the site.</li><li><strong>Visitor tasks</strong> Check menus, downloads, mobile layouts and the enquiry form, including failure states.</li><li><strong>Operations</strong> Agree the deployment owner, monitoring, backup/rollback responsibilities and post-launch checks.</li></ul><p>Use the <a href="/tools/website-brief-builder/">brief builder</a> to collect open decisions. For implementation, explore <a href="/services/nextjs-development/">Next.js and headless WordPress development</a> or <a href="/services/agency-development-support/">agency development support</a>.</p>')]),
    ('headless-wordpress-vs-traditional-wordpress', 'Headless vs Traditional WordPress | A Business Decision Guide',
     'Compare traditional WordPress and headless WordPress with Next.js by editing, preview, integrations and ownership. Includes a practical business decision worksheet.',
     'Headless WordPress or a traditional WordPress website?',
     'Choose the setup your visitors and publishing team can use and your team can maintain. WordPress and Next.js can work together; the decision is about the complete website and its owners.', [
         ('Compare complete setups', '<p>Traditional WordPress combines content management and the public presentation within its theme/plugin setup. A headless WordPress site keeps WordPress for content and adds a separate frontend, such as Next.js. A third option is a different CMS with a custom frontend.</p><p>That distinction matters when someone asks “WordPress or Next.js?” The combination can preserve a familiar publishing workspace while giving the frontend a different structure. It also creates another application to deploy and maintain.</p>'),
         ('A practical decision matrix', '<div class="tool-table-wrap" tabindex="0" role="region" aria-label="WordPress architecture comparison"><table class="tool-table"><thead><tr><th>Question</th><th>Traditional WordPress</th><th>WordPress + Next.js</th></tr></thead><tbody><tr><td>Who edits?</td><td>Editors use the configured WordPress workflow.</td><td>Editors use WordPress; fields must map to frontend components.</td></tr><tr><td>How does preview work?</td><td>Review theme and plugin behavior.</td><td>Agree draft access and a frontend preview route.</td></tr><tr><td>What happens to plugins?</td><td>Check compatibility with the installed theme.</td><td>Check each plugin\'s API/data and frontend requirements.</td></tr><tr><td>Who maintains it?</td><td>WordPress/theme/plugin owner.</td><td>CMS owner plus frontend/deployment ownership.</td></tr><tr><td>What about search?</td><td>Content, URLs and implementation still matter.</td><td>Content, URLs and implementation still matter.</td></tr></tbody></table></div>'),
         ('When a simpler site may fit', '<p>If your needs are standard pages, a familiar editing workflow and a form that an existing theme/plugin combination handles well, start by checking whether that setup already solves the task. Budget and the team\'s maintenance capability should be part of the decision.</p><p>A slow or confusing page does not by itself establish that the platform must be replaced. Review its content, assets, templates, third-party scripts and visitor journey before proposing a rebuild.</p>'),
         ('When a separate frontend is worth scoping', '<p>A headless approach may fit a custom interface, structured content reused across surfaces or a design that needs a deliberately built component system. Establish the frontend requirement and editorial workflow before committing to it.</p><p>My <a href="/project-case-study-2.html">Cambridge Research Park</a> and <a href="/project-case-study-3.html">1540 Broadway</a> case studies show attributed frontend and WordPress-content integration work. They are useful implementation evidence rather than universal evidence that every business needs the same architecture.</p>'),
         ('Use a concrete example', '<p>Imagine a fictional campus site with building pages, a maintained availability list and brochure downloads. First decide who updates each field. Then decide whether the existing presentation can show that content clearly. Finally, compare the build and maintenance responsibilities of each option.</p><p><a href="/resources/cms-content-example.json" download>Download the synthetic content model</a> and <a href="/resources/headless-decision-worksheet.txt" download>the decision worksheet</a>. Use the <a href="/tools/website-cost-calculator/">cost planning calculator</a> to expose scope assumptions, not to substitute an illustrative range for a project quote.</p>'),
         ('Prepare the implementation brief', '<p>Bring the current site, required page types, publishing frequency, plugins/integrations, existing design and expected support ownership. Separate requirements from preferences and record what needs testing.</p><p>Explore <a href="/services/nextjs-development/">freelance Next.js development</a> and the <a href="/insights/wordpress-to-nextjs-migration-checklist/">migration checklist</a>. A useful initial decision is one your editor, developer and business owner can all explain.</p>')]),
    ('saas-mvp-scope-template', 'SaaS MVP Scope Template | A Filled First-Release Example',
     'Prepare a SaaS MVP brief with one core workflow, roles, acceptance criteria and exclusions. Download an original blank template and a synthetic filled example.',
     'SaaS MVP scope template with a filled example',
     'Define a first release that someone can use end to end and a developer can estimate. Start with a user outcome, then document the data, access rules and acceptance checks needed to reach it.', [
         ('Choose one user and one task', '<p>A feature list such as “dashboard, chat and AI” leaves important decisions unresolved. Name the person, the task and the event that establishes success. For example: a support operator can read an assigned enquiry and record its next action.</p><p>That example is synthetic. The <a href="/project-case-study-1.html">ChatKnot case study</a> shows my real contribution to a connected SaaS workflow, while the scope below is a reusable planning exercise.</p>'),
         ('Write the complete first workflow', '<ol><li>A user signs in and sees only the enquiries they are allowed to access.</li><li>The user opens one enquiry and reads its current context.</li><li>The user records a response or next action.</li><li>The application confirms the write succeeded and retains the history.</li><li>If the request fails, the entered work remains available for retry.</li></ol><p>The first release needs these connected steps more than a large collection of unrelated screens. Identify the operator who handles exceptions as well as the normal user.</p>'),
         ('Separate required and deferred work', '<div class="tool-table-wrap" tabindex="0" role="region" aria-label="Synthetic MVP scope"><table class="tool-table"><thead><tr><th>Required in this example</th><th>Deferred in this example</th></tr></thead><tbody><tr><td>Authentication and enquiry access rules</td><td>Multiple billing plans</td></tr><tr><td>Read and record one next action</td><td>AI-generated response suggestions</td></tr><tr><td>Failure/retry behavior and history</td><td>Native mobile applications</td></tr><tr><td>Basic operator administration</td><td>Advanced analytics and exports</td></tr></tbody></table></div><p>Those exclusions are choices for this demonstration, not a rule that billing, AI or mobile must always come later. Your product\'s core outcome determines what is required.</p>'),
         ('Make acceptance observable', '<p>“Easy to use” needs more detail before it becomes an acceptance criterion. Write checks your team can perform: an unauthorized user cannot open the record; a successful save appears in history; a failed save retains the draft; the operator can see unresolved work.</p><p>Also agree test data, who reviews the release, the supported environments and what depends on an outside provider. If AI is required, add representative inputs and expected review/fallback behavior. See <a href="/services/ai-development/">AI application development</a> for that scope.</p>'),
         ('Download and fill the brief', '<p><a href="/resources/saas-mvp-scope-template.txt" download>Download the blank template</a> and <a href="/resources/saas-mvp-scope-example.txt" download>the synthetic filled example</a>. They cover the user, workflow, required scope, exclusions, data, roles, acceptance, dependencies and open budget/timing questions.</p><p>The <a href="/tools/website-brief-builder/">brief builder</a> also includes a product/SaaS path. For two-sided booking or services products, use the separate <a href="/insights/service-marketplace-mvp-checklist/">marketplace MVP checklist</a> to consider both sides of the exchange.</p>'),
         ('Bring the open questions to an estimate', '<p>A useful estimate includes assumptions, dependencies and exclusions. Share what already exists, any current code or design, required integrations and your intended launch or pilot. Agree the owner of ongoing support before release.</p><p>Explore <a href="/services/saas-mvp-development/">SaaS MVP development</a> and <a href="/services/service-marketplace-app-development/">marketplace development</a> for implementation. A complete small workflow is an easier starting point for review than an unbounded feature wishlist.</p>')])
]

if __name__ == '__main__':
    for slug, title, description, h1, intro, sections in GUIDES:
        render('/insights/' + slug + '/', title, description, h1, intro, ''.join(section(h, b) for h, b in sections), kind='guide')
    ai_cards = ''.join(f'<article class="evidence-card"><h3><a href="/services/{p["slug"]}/">{p["name"]}</a></h3><p>{p["description"]}</p></article>' for p in services[:6])
    web_items = [('nextjs-development', 'Next.js & headless WordPress', 'Responsive websites and editor-managed content with relevant UK and New York project work.'), ('agency-development-support', 'Agency development support', 'Frontend implementation, review and handover around an agency-supplied brief.'), ('commercial-property-websites', 'Commercial property websites', 'Building, campus, availability and enquiry journeys.'), ('saas-mvp-development', 'SaaS MVP development', 'Interfaces, APIs and data connected around a complete product workflow.'), ('service-marketplace-app-development', 'Service marketplace applications', 'Customer, provider and operator journeys for a two-sided service product.'), ('data-import-integration', 'Data imports & API integration', 'Mapping, validation and reviewed data handoffs between business systems.')]
    web_cards = ''.join(f'<article class="evidence-card"><h3><a href="/services/{slug}/">{name}</a></h3><p>{copy}</p></article>' for slug, name, copy in web_items)
    body = section('AI applications and business automation', '<p>Choose the outcome you need: an application feature, a knowledge assistant, a call or messaging workflow, or an integration between existing apps.</p><div class="evidence-grid">' + ai_cards + '</div>', 'ai-services')
    body += section('Websites, SaaS and implementation support', '<div class="evidence-grid">' + web_cards + '</div>', 'web-services')
    body += section('A useful starting brief', '<p>Share the current workflow, the result you need, the systems involved, a budget range and any existing design or code. We can agree the first scope, acceptance checks and delivery responsibilities.</p><p>For a full-time role, share the team context and required working-hour overlap. Based in Karachi, I work remotely with UK and US teams. <a href="/Hasnain-Qureshi-Resume.pdf">View my resume</a> or explore <a href="/#work">selected project contributions</a>.</p>')
    render('/services/', 'AI, Automation & Full-Stack Development Services | Hasnain Qureshi', 'AI development, RAG chatbots, voice receptionists, WhatsApp, n8n and Zapier automation alongside Next.js, SaaS and website development for UK and US teams.', 'AI, automation and full-stack development services', 'Choose a focused implementation for your next product or business workflow. Explore the scope, relevant engineering evidence and information needed to start a project.', body, kind='hub')
    print('Rendered three original guides and the services hub.')
